*::before,
*::after {
  box-sizing: border-box;
}

[data-theme=light] {
  --bg: #f7f7f9;
  --surface: #ffffff;
  --text: #1a1a1f;
  --button: #e3e5ea;
  --button-hover: #c4c8d2;
  --accent: #b34700;
  --accent-hover: #7a2f00;
  --focus-ring: #0b57d0;
}

[data-theme=dark] {
  --bg: #0b0b0e;
  --surface: #1b1c22;
  --text: #f2f2f5;
  --button: #34363f;
  --button-hover: #50535f;
  --accent: #ff9f43;
  --accent-hover: #ffc078;
  --focus-ring: #7fb2ff;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg);
  color: var(--text);
}

:has(> #keypad) {
  width: 100%;
  max-width: 400px;
  margin: 0 auto;
  padding: 12px;
  background-color: var(--surface);
  color: var(--text);
}

#display {
  min-width: 0;
  width: 100%;
  min-height: 64px;
  margin-bottom: 12px;
  padding: 12px;
  text-align: right;
  font-size: 2rem;
  overflow-wrap: anywhere;
  word-break: break-all;
  background-color: var(--bg);
  color: var(--text);
  border: 1px solid var(--button-hover);
  border-radius: 6px;
}

#keypad {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

#keypad [data-action=clear],
#keypad [data-action=backspace] {
  grid-column: span 2;
}

button {
  min-width: 0;
  min-height: 48px;
  padding: 8px;
  font: inherit;
  font-size: 1.25rem;
  color: var(--text);
  background-color: var(--button);
  border: 1px solid var(--button-hover);
  border-radius: 6px;
  cursor: pointer;
}

button[data-op],
button[data-action=equals],
button[data-action=clear] {
  background-color: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

button:hover {
  background-color: var(--button-hover);
}

button[data-op]:hover,
button[data-action=equals]:hover,
button[data-action=clear]:hover {
  background-color: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

#theme-toggle {
  display: block;
  width: 100%;
  max-width: 100%;
  margin-top: 12px;
  font-size: 1rem;
}
